Voces.initLearning=function(){
 const $=id=>document.getElementById(id);
 const qs=[
 {q:'Si una tasa es 59,7 %, ¿por qué iluminamos 60 puntos?',a:['Porque redondeamos la representación visual','Porque la fuente dice exactamente 60 %','Porque contamos 60 personas identificables'],ok:0,f:'Cada punto representa aproximadamente un punto porcentual. Redondear el dibujo no cambia el valor publicado: 59,7 %.'},
 {q:'Una tasa pasa de 50 % a 60 %. ¿Cuál es el cambio?',a:['10 % relativo y 20 puntos porcentuales','10 puntos porcentuales y 20 % relativo','10 personas más en todo el país'],ok:1,f:'60 − 50 = 10 puntos porcentuales. El cambio relativo divide esa diferencia por el valor inicial: 10 ÷ 50 × 100 = 20 %. Es un ejemplo didáctico, no otro dato CCPC.'},
 {q:'¿Qué comparación temporal tiene un contexto más adecuado?',a:['2021 y 2024 sin explicar sus diferencias','Cualquier año demuestra el efecto de una campaña','2018 y 2024, ambas presidenciales'],ok:2,f:'Separar presidenciales e intermedias evita mezclar procesos de distinto tipo. Aun así, no controla todas las diferencias ni prueba causas.'},
 {q:'Una entidad tiene una tasa distinta de la nacional. ¿Qué sabemos?',a:['Que observamos una diferencia agregada','Por qué decidió votar cada persona','Que sus habitantes tienen una sola opinión'],ok:0,f:'Una tasa territorial describe un agregado. No revela motivaciones ni permite atribuir a cada habitante las características del conjunto.'},
 {q:'¿Qué ayuda a leer honestamente una gráfica de barras?',a:['Ocultar la escala para simplificar','Usar la misma escala desde cero y mostrar las tasas','Cambiar la escala para exagerar diferencias'],ok:1,f:'Una escala común de 0 a 100 %, etiquetas numéricas y fuente visible permiten juzgar la magnitud. El color debe acompañarse de texto.'}
 ];let at=0,score=0,answered=false;
 function draw(focus=false){answered=false;const q=qs[at];$('quizBody').hidden=false;$('quizResult').hidden=true;$('quizQuestion').textContent=q.q;$('quizQuestion').tabIndex=-1;$('quizCounter').textContent=`PREGUNTA ${at+1} DE ${qs.length}`;$('quizScore').textContent=`${score} de ${qs.length} aciertos`;$('quizFeedback').textContent='';$('nextQuestion').disabled=true;$('nextQuestion').textContent=at===qs.length-1?'Ver lo aprendido →':'Siguiente pregunta →';$('quizAnswers').replaceChildren(...q.a.map((text,i)=>{const b=document.createElement('button');b.type='button';b.className='quiz-option';b.textContent=text;b.onclick=()=>answer(i);return b;}));if(focus)$('quizQuestion').focus();}
 function answer(i){if(answered)return;answered=true;const q=qs[at];if(i===q.ok)score++;Array.from($('quizAnswers').children).forEach((b,j)=>{b.disabled=true;if(j===q.ok){b.classList.add('correct');b.textContent='✓ '+b.textContent;}else if(j===i){b.classList.add('incorrect');b.textContent='✕ '+b.textContent;}});$('quizProgress').value=at+1;$('quizScore').textContent=`${score} de ${qs.length} aciertos`;$('quizFeedback').textContent=(i===q.ok?'Correcto. ':'Vamos a revisarlo. ')+q.f;$('nextQuestion').disabled=false;$('nextQuestion').focus();}
 $('nextQuestion').onclick=()=>{if(at<qs.length-1){at++;draw(true);}else{$('quizBody').hidden=true;$('quizResult').hidden=false;$('quizResult').innerHTML=`<div class="overline">RECORRIDO COMPLETADO</div><h3>${score} de ${qs.length} respuestas correctas</h3><p>Ya practicaste cinco ideas para compartir datos con cuidado:</p><ul><li>Los puntos ilustran; la tasa conserva su decimal.</li><li>Puntos porcentuales y cambio relativo son distintos.</li><li>El tipo de elección importa.</li><li>Un agregado no explica a cada persona.</li><li>Escala, etiquetas y fuente hacen legible una gráfica.</li></ul><p>Puedes repetirlo: aprender no requiere acertar todo a la primera.</p>`;$('quizResult').focus();}};
 $('restartQuiz').onclick=()=>{at=0;score=0;$('quizProgress').value=0;draw(true);};draw();
};
